local Knit=require(game:GetService("ReplicatedStorage"):WaitForChild("Knit")); local S=Knit.CreateService({Name="GuildService",Client={Create=Knit.CreateSignal(),Join=Knit.CreateSignal(),Leave=Knit.CreateSignal(),Manage=Knit.CreateSignal(),GuildUpdated=Knit.CreateSignal()}}); S.Guilds={}
function S:CreateGuild(p,name,tag) local d=self.Services.PlayerDataService:GetData(p); if not d or d.captainData.CaptainRank=="Deckhand" then return false,"Captain rank required" end; if type(name)~="string" or #name<2 or #name>16 or type(tag)~="string" or #tag<2 or #tag>4 then return false,"Invalid name" end; local id=tostring(p.UserId); if self.Guilds[id] then return false,"Already in guild" end; self.Guilds[id]={Id=id,Name=name,Tag=tag,Level=1,XP=0,Members={[p.UserId]="Captain"},Treasury=0,CreatedAt=os.time()}; d.GuildId=id; self.Services.PlayerDataService:SaveData(p); return true,id end
function S:JoinGuild(p,id) local g=self.Guilds[tostring(id)]; local d=self.Services.PlayerDataService:GetData(p); if not g or not d or d.GuildId then return false end; local n=0 for _ in pairs(g.Members) do n+=1 end; if n>=(g.Level+1)*2+6 then return false,"Guild full" end; g.Members[p.UserId]="Member"; d.GuildId=g.Id; self.Services.PlayerDataService:SaveData(p); return true end
function S:LeaveGuild(p) local d=self.Services.PlayerDataService:GetData(p); local g=d and self.Guilds[d.GuildId]; if not g or g.Members[p.UserId]=="Captain" then return false end; g.Members[p.UserId]=nil; d.GuildId=nil; self.Services.PlayerDataService:SaveData(p); return true end
function S:KnitInit() self.Client.Create:Connect(function(...)return self:CreateGuild(...)end); self.Client.Join:Connect(function(...)return self:JoinGuild(...)end); self.Client.Leave:Connect(function(p)return self:LeaveGuild(p)end) end
return S
